-- Correzione encoding: testi ricopiati dal vecchio progetto in forma pura ASCII (\uXXXX)
UPDATE public.immobili SET codice = E'Frisi 9', titolo = E'Trilocale luminoso con terrazzo ', categoria = E'Appartamento', citta = E'Milano', zona = E'Porta Venezia', indirizzo = E'Via Paolo Frisi 9', piano = E'4', stato = E'Ristrutturato', classe_energetica = E'F', riscaldamento = E'Autonomo', descrizione = E'A Milano, nel cuore di Porta Venezia e ottimamente servita, proponiamo in vendita un luminoso trilocale disposto su due livelli, situato al quarto e quinto ( ultimo piano ) di uno stabile dotato di ascensore. L\u2019appartamento si distingue per la sua particolare distribuzione interna, che garantisce spazi ben separati e funzionali, ideali per chi cerca una soluzione accogliente, per investimento o da personalizzare nel cuore della citt\u00e0.\n\nAl primo livello troviamo un ingresso che si apre su un comodo disimpegno. Da qui si accede alla cucina abitabile, presente una prima stanza, che pu\u00f2 essere utilizzata come camera da letto, studio o zona hobby, a seconda delle esigenze ed infine un bagno con vasca.\n\nSalendo al secondo livello tramite una scala interna si accede alla zona giorno, caratterizzata da un luminoso soggiorno con camino decorativo, che dona un tocco di calore e raffinatezza all\u2019ambiente. Su questo piano si trova anche la camera matrimoniale con accesso diretto a un gradevole TERRAZZINO, perfetto per godere di momenti di relax all\u2019aperto. Completa il piano un secondo bagno finestrato con box doccia.\n\nL\u2019immobile \u00e8 situato in un contesto urbano vivace e ben collegato: a soli cinque minuti a piedi si raggiunge la fermata della metropolitana Porta Venezia (Linea Rossa), mentre nelle immediate vicinanze si trovano diverse linee di superficie, tra cui i tram e autobus che consentono di spostarsi comodamente in tutta la citt\u00e0.\nLa zona \u00e8 particolarmente apprezzata per la sua vicinanza al centro e per la presenza di numerosi servizi, tra cui supermercati, negozi di prima necessit\u00e0, boutique di antiquariato, ristoranti di ogni tipo \u2013 dai locali pi\u00f9 ricercati a quelli etnici e accessibili \u2013 che contribuiscono a rendere il quartiere dinamico e piacevole da vivere.\n\nQuesta soluzione rappresenta una scelta ideale per investimento o piccoli nuclei familiari che desiderano abitare in un appartamento unico nel suo genere, da personalizzare o pronto da vivere e in una delle zone pi\u00f9 ambite di Milano.\n\nConsigliata la visione.\nPer maggiori informazioni e per fissare un appuntamento, non esitate a contattarci.', caratteristiche = ARRAY[E'Terrazzo panoramico',E'Doppia esposizione',E'Aria condizionata',E'Portineria']::text[] WHERE id = 1;
UPDATE public.immobili SET codice = E'Piave', titolo = E'Immobile con Terrazzo', categoria = E'Villa', citta = E'Milano', zona = E'Zona Indipendenza / Risorgimento', indirizzo = E'Viale Piave', piano = E'4', stato = E'Ottimo', classe_energetica = E'F', riscaldamento = E'Autonomo', descrizione = E'Proponiamo la vendita della NUDA PROPRIETA'' di tre appartamenti situati in Zona Viale Piave, Milano, in una delle zone pi\u00f9 eleganti e servite della citt\u00e0. Gli immobili si trovano al 3\u00b0 e 4\u00b0 piano di un edificio signorile con servizio di portineria tutto il giorno, doppio ingresso, doppio ascensore e riscaldamento centralizzato. La propriet\u00e0 \u00e8 composta da un appartamento di circa 120 mq commerciale al 4\u00b0 piano, con un terrazzo di 110 mq e balcone, e da due appartamenti di 45 mq + 61 mq commerciali al 3\u00b0 piano, uno con balcone. Gli immobili sono dotati di aria condizionata e due cantine di pertinenza. Grazie alla sua disposizione unica, l\u2019immobile offre ampie possibilit\u00e0 di personalizzazione.\nUn\u2019opportunit\u00e0 unica per chi cerca una propriet\u00e0 di valore in una delle zone pi\u00f9 ricercate di Milano. \nPer maggiori informazioni e dettagli sulla nuda propriet\u00e0, non esitate a contattarci.', caratteristiche = ARRAY[E'Terrazzo',E'Luminosit\u00e0',E'Balcone']::text[] WHERE id = 2;
UPDATE public.immobili SET codice = E'Liberty 20', titolo = E'Bilocale totalmente ristrutturato con ampio balcone/terrazzo', categoria = E'Appartamento', citta = E'Milano', zona = E'Porta Venezia', indirizzo = E'Via Antonio Stoppani 40', piano = E'4', stato = E'Nuovo', classe_energetica = E'E', riscaldamento = E'Autonomo', descrizione = E'Bilocale totalmente ristrutturato con ampio balcone/terrazzo\n\nProponiamo in locazione splendido bilocale completamente ristrutturato, situato al quarto e penultimo piano di uno stabile ben tenuto.\nL\u2019appartamento \u00e8 composto da ingresso dal terrazzo su luminoso soggiorno con cucina a vista, la zona notte \u00e8 composta da una spaziosa camera da letto matrimoniale, anch\u2019essa con accesso al proprio balcone, e da un bagno moderno dotato di box doccia.\nCanone di locazione: \u20ac 1.600 / mese\nSpese condominiali: \u20ac 100 / mese\nCondizioni:\n\u2022 pagamento mensile\n\u2022 3 mesi di deposito cauzionale\n\u2022 utenze luce, gas e TARI a carico dell\u2019inquilino\n\u2022 disponibile da subito\nPer maggiori informazioni o per fissare una visita non esitate a contattarci.', caratteristiche = ARRAY[E'Balcone',E'Aria condizionata',E'Ascensore',E'Terrazzo']::text[] WHERE id = 3;
UPDATE public.immobili SET codice = E'City Lifi-RH', titolo = E'CityLife \u2013 Residenza Hadid', categoria = E'Appartamento', citta = E'Milano', zona = E'City Life', indirizzo = E'Via Senofonte 4', piano = E'5', stato = E'Nuovo', classe_energetica = E'A', riscaldamento = E'Centralizzato', descrizione = E'Nel cuore del pi\u00f9 esclusivo quartiere di Milano, all''interno delle iconiche residenze firmate Zaha Hadid, proponiamo in locazione un raffinato bilocale di 112 mq situato al 5\u00b0 piano con ascensore, inserito in un contesto di assoluto prestigio con servizi di alto livello. L''appartamento si distingue per l''elegante zona living caratterizzata da ampie vetrate a tutta altezza che garantiscono straordinaria luminosit\u00e0 e una perfetta continuit\u00e0 tra interno ed esterno; gli spazi, curati nei minimi dettagli, sono valorizzati da arredi su misura, lampade di design e pannelli scorrevoli che separano la zona divano dalla zona pranzo, disimpegno con armadiature su misura e la cucina abitabile, separata e completamente attrezzata, ulteriore disimpegno, bagno di servizio con angolo lavanderia, cabina armadio e camera da letto che d\u00e0 accesso al terrazzo, ed infine bagno principale con ulteriore accesso sul terrazzo.\nElemento distintivo della propriet\u00e0 \u00e8 il magnifico terrazzo angolare, sviluppato su due lati, che offre una suggestiva vista aperta a 180\u00b0 sul parco CityLife e sullo skyline, incluse le iconiche torri, rappresentando uno spazio ideale per momenti di relax e convivialit\u00e0 all''aperto.\nL''immobile presenta finiture di alto standing quali parquet, serramenti ad elevate prestazioni e impianto centralizzato con pompa di calore per il massimo comfort abitativo in ogni stagione.\nLa propriet\u00e0 si trova all''interno di un contesto esclusivo dotato di servizio di portineria e sicurezza H24, area wellness e fitness, spazi comuni di rappresentanza, deposito biciclette e sistemi di domotica.\nCanone mensile pari a \u20ac 9.160, 00 oltre spese condominiali di \u20ac 840 mensili, contratto in cedolare secca, disponibilit\u00e0 a partire dal 1\u00b0 maggio 2026.\nPer maggiori informazioni o per fissare una visita non esiti a contattarci.\nStudio Arte Immobiliare.', caratteristiche = ARRAY[E'Vista',E'Terrazzo',E'Area Wellness',E'Sicurezza 24H',E'Skyline']::text[] WHERE id = 4;
UPDATE public.immobili SET codice = E'Giga', titolo = E'Trilocale con terrazzo in Porta Venezia a Milano', categoria = E'Appartamento', citta = E'Milano', zona = E'Porta Venezia', indirizzo = E'Via Antonio Stoppani 40', piano = E'4', stato = E'Buono', classe_energetica = E'In corso', riscaldamento = E'Autonomo', descrizione = E'Proponiamo in locazione meraviglioso trilocale situato al quarto piano con ascensore, in un palazzo stile liberty e ben abitato, composto da ingresso su angolo cottura con zona pranzo, luminoso soggiorno con divano letto e accesso a terrazzo vivibile, camera da letto con bagno finestrato e box doccia, secondo bagno finestrato con vasca e seconda camera da letto.\n\nIl canone richiesto \u00e8 di \u20ac 2.100, 00 mensili, oltre \u20ac 200,00 di spese condominiali, comprensive di servizio di portierato full-time ( dal luned\u00ec a venerd\u00ec e sabato mezza giornata), ascensore e gestione delle parti comuni.\n\nLe utenze (luce, gas, internet e TARI \u2013 tassa comunale sui rifiuti da versare al Comune di Milano) sono a carico dell\u2019inquilino.\n\nL\u2019immobile sar\u00e0 disponibile a partire dal 1\u00b0 maggio 2026.\n\nSono richiesti tre mesi di deposito cauzionale.\n\nPer maggiori informazioni o per fissare una visita, restiamo a completa disposizione.', caratteristiche = ARRAY[E'Terrazzo',E'Luminoso',E'Aria condizionata']::text[] WHERE id = 5;
UPDATE public.immobili SET codice = E'Big', titolo = E'Trilocale con due balconi in Porta Venezia a Milano ', categoria = E'Appartamento', citta = E'Milano', zona = E'Porta Venezia', indirizzo = E'Via Antonio Stoppani 40', piano = E'2', stato = E'Buono', classe_energetica = E'In corso', riscaldamento = E'Autonomo', descrizione = E'Porta Venezia \u2013 Elegante trilocale ristrutturato con balcone e doppi servizi\nIn una delle zone pi\u00f9 richieste di Milano, a pochi passi da Porta Venezia, proponiamo in locazione un raffinato appartamento situato al secondo piano di un elegante palazzo d\u2019epoca in stile Liberty, dotato di ascensore e servizio di portineria attivo tutto il giorno.\nL\u2019immobile, recentemente ristrutturato, si presenta in ottime condizioni ed \u00e8 completo di aria condizionata. Gli spazi sono ben distribuiti e luminosi, ideali per chi cerca comfort e funzionalit\u00e0 in un contesto signorile.\n\nL\u2019appartamento \u00e8 cos\u00ec composto:\n\u2022ingresso su disimpegno\n\u2022soggiorno con angolo cottura e accesso al balcone\n\u2022due camere matrimoniali\n\u2022due bagni\n\nDisponibile da subito\n\nCanone di locazione agevolato:\n\u20ac 1.800/mese per i primi 2 anni + spese condominiali\n\u20ac 2.100/mese dal 3\u00b0 anno + spese condominiali\n\nSpese condominiali: \u20ac 150/mese, comprensive di ascensore, portineria, pulizia parti comuni e luce condominiale.\n\nUtenze (luce, gas, Tari, acqua, internet) a parte.\nDeposito cauzionale pari a tre mensilit\u00e0.\nSoluzione ideale per studenti referenziati o lavoratori.\nPer maggiori informazioni o per fissare un appuntamento, restiamo a completa disposizione.', caratteristiche = '{}'::text[] WHERE id = 6;
UPDATE public.immobili SET codice = E'Voghera', titolo = E'Bilocale con 2 balconi in Porta Genova a Milano', categoria = E'Appartamento', citta = E'Via Voghera 11', zona = E'Porta Genova', indirizzo = E'', piano = E'5', stato = E'Buono', classe_energetica = E'E', riscaldamento = E'Centralizzato', descrizione = E'Proponiamo in locazione meraviglioso bilocale situato al quinto piano con ascensore, composto da ingresso su luminoso soggiorno con accesso al balcone, ampio angolo cottura, disimpegno con pratico angolo lavanderia, bagno finestrato e spaziosa camera matrimoniale con secondo balcone/terrazzino.\n\nL\u2019immobile \u00e8 situato in zona Porta Genova, a due passi dalla metropolitana e in posizione strategica, comoda per universit\u00e0 e principali servizi.\n\nIl canone richiesto \u00e8 di \u20ac 1.550,00 mensili, oltre \u20ac 150,00 di spese condominiali, comprensive di riscaldamento, servizio di portierato mezza giornata, ascensore e gestione delle parti comuni.\n\nLe utenze (luce, gas, internet e TARI \u2013 tassa comunale sui rifiuti da versare al Comune di Milano) sono a carico dell\u2019inquilino.\n\nL\u2019immobile sar\u00e0 disponibile a partire da agosto 2026.\n\nSono richiesti tre mesi di deposito cauzionale.\n\nPer maggiori informazioni o per fissare una visita, restiamo a completa disposizione.', caratteristiche = ARRAY[E'2 balconi',E'aria condizionata',E'piano alto',E'luminoso']::text[] WHERE id = 7;
UPDATE public.immobili SET codice = E'Figini', titolo = E'Bilocale a piano alto', categoria = E'Appartamento', citta = E'Milano', zona = E'Porta Venezia', indirizzo = E'Via Antonio Stoppani 40', piano = E'3', stato = E'Buono', classe_energetica = E'G', riscaldamento = E'Autonomo', descrizione = E'BILOCALE ARREDATO IN VIA STOPPANI, PORTA VENEZIA\nPorta Venezia, Via Antonio Stoppani 40 \u2013 In una delle zone pi\u00f9 servite e ben collegate di Milano, proponiamo in locazione un ampio appartamento arredato, situato al terzo piano con ascensore.\nL''immobile si compone di: ingresso con disimpegno, ampia camera da letto, luminoso ambiente con angolo salottino, cucina abitabile di generose dimensioni utilizzabile anche come soggiorno e ampio bagno finestrato.\nL''appartamento \u00e8 arredato, in buone condizioni e disponibile da subito. Posizione strategica a pochi passi dai Giardini Pubblici Indro Montanelli, dalla fermata della metropolitana di Porta Venezia e da tutti i principali servizi di zona.\nSi segnala che l''immobile non \u00e8 dotato di aria condizionata.\nCanone mensile: 1.300 euro + 100 euro di spese condominiali. Utenze (luce, gas e TARI) a carico del conduttore. Si richiedono 3 mensilit\u00e0 di deposito cauzionale.\nLibero subito. Per maggiori informazioni, siamo a completa disposizione.', caratteristiche = '{}'::text[] WHERE id = 8;
UPDATE public.immobili SET codice = E'Liberty 12', titolo = E'Bilocale con Balcone a Milano in Porta Venezia', categoria = E'Appartamento', citta = E'Milano', zona = E'Porta Venezia', indirizzo = E'Via Antonio Stoppani 40', piano = E'2', stato = E'Buono', classe_energetica = E'In corso', riscaldamento = E'Autonomo', descrizione = E'Appartamento con balcone al secondo piano con ascensore in zona Porta Venezia. L\u2019immobile e ben rifinito, si compone di ingresso su soggiorno con cucina a vista con balcone, camera matrimoniale e bagno. L\u2019immobile si trova a brevissima distanza da Porta Venezia e Corso Buenos Aires, in una posizione strategica che unisce la comodit\u00e0 del centro storico di Milano alla tranquillit\u00e0 di una zona residenziale ricca di servizi. Disponibile da subito. Canone mensile di 1.200 euro oltre 100 euro di spese condominiali comprensive di servizio di portineria attivo tutto il giorno, ascensore, pulizia e spese comuni, utenze a parte. Non \u00e8 presente l''aria condizionata. \nDisponibile a fine Aprile 2026.\nRichieste ottime referenze. Per maggiori informazioni e per organizzare una visita non esitate a contattarci', caratteristiche = ARRAY[E'Balcone',E'No Aria Condizionata']::text[] WHERE id = 9;
UPDATE public.immobili SET codice = E'Villetta V1', titolo = E'Villette con Piscina Privata e Vista Lago!!!!', categoria = E'Villa', citta = E'Gravedona ed Uniti', zona = E'', indirizzo = E'Localit\u00e0 Traversa 37', piano = E'', stato = E'Buono', classe_energetica = E'In corso', riscaldamento = E'Autonomo', descrizione = E'Lago Como Gravedona ed Uniti \u2013 in moderno edificio con ampie vetrate PRENOTASI due eleganti villette semindipendenti con piscina privata e vista lago. \n\nA soli 3 km dal Lago di Como... in un\u2019oasi di tranquillit\u00e0, SOLE e luce.. nasce un edificio unico nel suo genere: una creazione architettonica dal design moderno, caratterizzata da ampie vetrate che catturano il sole durante tutto il giorno e aprono lo sguardo verso un panorama sereno e suggestivo.\n\nL\u2019edificio ospita due villette semindipendenti: ognuna libera su tre lati, con un giardino privato, ideale per momenti all\u2019aperto in totale riservatezza, un posto auto esclusivo e la piscina privata 5 x 3 metri, illuminata e dotata soffione e doccia a cascata, pensata per regalare spazi di relax con vista sul paesaggio naturale circostante. \n\nLa Disposizione interna delle Villette si sviluppa su tre livelli:\n- Piano interrato: Locale tecnico con impianti piscina, ripostiglio predisposto per eventuale secondo bagno e Locale hobby versatile (palestra, sala giochi, studio, deposito attrezzature)\n- Piano terra: Ampia zona giorno con grande vetrata panoramica e angolo cottura, camera matrimoniale, bagno finemente rifinito, accesso diretto al giardino e alla piscina\n- Piano primo Seconda zona living con spettacolare apertura verso la vista, camera matrimoniale aggiuntiva, secondo bagno\nOgni abitazione dispone della propria piscina privata 5 x 3 metri, illuminata e dotata soffione e doccia a cascata, oltre che da un soleggiato giardino privato esposto a SUD.\n\nEntrambe le soluzioni godono di una bella vista lago e monti, concepite con linee moderne, grandi superfici vetrate e materiali di alta qualit\u00e0.\n\nVilletta V1 - 122 mq abitazione - 210 mq di giardino privato - posto auto privato - Prezzo: \u20ac 740.000 + IVA\n\nVilletta V2 - 122 mq abitazione  - 190 mq di giardino privato - posto auto privato - Prezzo: \u20ac 680.000 + IVA\n\n\n\nDotazioni tecniche e finiture previste di moderna concezione progettuale.\n\nAmpie vetrate panoramiche che illuminano tutti gli ambienti\nImpianto di climatizzazione estate/inverno con pompa di calore e split ad aria, con Bollitore in pompa di calore con accumulo da 200 litri\nPavimenti in quarzo calcestruzzo lucidato con resina protettiva antimacchia; Interni con pareti e plafoni in calcestruzzo faccia a vista trattato con protettivo\nParapetti in lamiera piena per un design pulito e contemporaneo\nPareti esterne in calcestruzzo facciavista grezzo\nTravi a vista in legno e copertura isolata con rivestimento in lamiera color antracite\nRubinetteria Newform \u2013 Serie Linfa - e Sanitari Azzurra filo muro \u2013 Serie Comoda - \nPiatto doccia in resina antiscivolo con rivestimento in grandi lastre 60\u00d7120 Floris \u2013 Serie Neutra\nImpianto elettrico Serie Living nera\nFiniture completamente personalizzabili secondo le esigenze del cliente\nPerch\u00e9 scegliere queste villette\n\nA soli 3 km dal Lago di Como, con Vista aperta e privacy\nArchitettura moderna e materiali ricercati, con la Possibilit\u00e0 di personalizzare finiture e soluzioni interne\nIdeali come prima casa, casa vacanza o investimento.\n', caratteristiche = ARRAY[E'Piscina',E'Giardino',E'Posto auto']::text[] WHERE id = 10;
UPDATE public.immobili SET codice = E'Villetta V2 ', titolo = E'Villette con Piscina Privata e Vista Lago!!!!', categoria = E'Villa', citta = E'Gravedona ed Uniti', zona = E'', indirizzo = E'Localit\u00e0 Traversa 37', piano = E'', stato = E'Nuovo', classe_energetica = E'In corso', riscaldamento = E'Autonomo', descrizione = E'Villette con Piscina Privata e Vista Lago!!!!\n\nLago di Como Gravedona ed Uniti\nIn posizione tranquilla e soleggiata, a soli 3 km dal lago, prenotasi due eleganti villette semindipendenti di nuova costruzione, caratterizzate da un design moderno con ampie vetrate, piscina privata e vista lago e monti.\n\nLe villette, inserite in un edificio unico nel suo genere, sono libere su tre lati e dotate di giardino privato esposto a sud, ideale per vivere gli spazi esterni in completa privacy. Ogni unit\u00e0 dispone inoltre di posto auto privato e di una piscina 5\u00d73 m illuminata, con soffione e doccia a cascata.\n\nDistribuzione interna \u2013 122 mq su 3 livelli\n\nPiano interrato:\nLocale tecnico piscina, ripostiglio predisposto per eventuale secondo bagno, ampio locale hobby (palestra, studio, sala giochi).\n\nPiano terra:\nLuminosissima zona giorno con grande vetrata panoramica e angolo cottura, camera matrimoniale, bagno finemente rifinito, accesso diretto al giardino e alla piscina.\n\nPiano primo:\nSeconda zona living con splendida apertura verso la vista, seconda camera matrimoniale, bagno.\n\nSpazi esterni\n\n\u2022 Giardino privato (210 mq V1 \u2013 190 mq V2)\n\u2022 Piscina esclusiva 5\u00d73 m\n\u2022 Esposizione solare ottimale a sud\n\nPrezzi\n\n\u2022 Villetta V1 \u2013 \u20ac 740.000 + IVA (122 mq + 210 mq giardino + posto auto)\n\u2022 Villetta V2 \u2013 \u20ac 680.000 + IVA (122 mq + 190 mq giardino + posto auto)\n\nDotazioni e finiture\n\n\u2022 Ampie vetrate panoramiche\n\u2022 Impianto clima caldo/freddo con pompa di calore \u2013 bollitore 200 lt\n\u2022 Pavimenti in quarzo-calcestruzzo con resina protettiva\n\u2022 Interni in calcestruzzo faccia a vista trattato\n\u2022 Parapetti in lamiera piena dal design contemporaneo\n\u2022 Copertura isolata con travi a vista e finitura in lamiera antracite\n\u2022 Rubinetteria Newform serie Linfa \u2013 Sanitari Azzurra serie Comoda\n\u2022 Piatto doccia in resina antiscivolo + rivestimento lastre 60\u00d7120 Floris\n\u2022 Impianto elettrico Serie Living nero\n\u2022 Finiture personalizzabili su richiesta\n\nPerch\u00e9 sceglierle\n\n\u2022 Modernit\u00e0 e privacy a pochi minuti dal lago\n\u2022 Vista aperta su lago e montagne\n\u2022 Spazi luminosi grazie alle grandi vetrate\n\u2022 Piscina privata e giardino esposto a sud\n\u2022 Perfette come prima casa, casa vacanza o investimento.', caratteristiche = '{}'::text[] WHERE id = 11;
UPDATE public.immobili SET codice = E'VillaLomazzo', titolo = E'ELEGATE VILLA CON PARCO DI 2.000MQ E PISCINA-NUDA PROPRIETA''', categoria = E'Villa', citta = E'Lomazzo', zona = E'', indirizzo = E'Via Ceresio', piano = E'Terra', stato = E'Buono', classe_energetica = E'G', riscaldamento = E'Autonomo', descrizione = E'Proponiamo in vendita la nuda propriet\u00e0 di un\u2019elegante villa immersa nella quiete di un magnifico parco privato di circa 2.000 mq, una propriet\u00e0 di rara reperibilit\u00e0 nel comune di Lomazzo.\nLa residenza, realizzata negli anni \u201980, si sviluppa su circa 250 mq distribuiti su due livelli e offre ambienti ampi, luminosi e armoniosamente integrati con il verde circostante, grazie alle grandi vetrate che regalano splendide viste sul giardino e sulla piscina.\nIl vero protagonista della propriet\u00e0 \u00e8 il parco: un autentico angolo di natura, impreziosito da alberi secolari e da una vegetazione rigogliosa che assicura privacy assoluta, silenzio e un\u2019atmosfera di pace in ogni stagione.\nLa splendida piscina interrata si inserisce perfettamente nel paesaggio, creando una naturale continuit\u00e0 tra gli spazi interni ed esterni e trasformando la villa in un luogo ideale dove vivere momenti di relax e convivialit\u00e0.\nRealizzata con le caratteristiche delle prestigiose abitazioni dell\u2019epoca, la villa conserva il fascino delle costruzioni degli anni \u201980, con ambienti generosi, soffitti importanti e una distribuzione degli spazi studiata per garantire comfort e funzionalit\u00e0.\n\nLa posizione \u00e8 particolarmente strategica: Lomazzo, a pochi minuti dall\u2019ingresso autostradale, consente di raggiungere comodamente Milano, Como e il confine svizzero, coniugando la tranquillit\u00e0 di un contesto riservato con la comodit\u00e0 dei principali collegamenti.\nUna residenza dove natura, privacy ed eleganza si fondono in perfetto equilibrio, rappresentando un\u2019opportunit\u00e0 unica per chi desidera investire in un immobile destinato a conservare il proprio valore nel tempo\nPer maggiori informazioni o per organizzare una visita, saremo lieti di accompagnarvi alla scoperta di questa esclusiva propriet\u00e0.', caratteristiche = ARRAY[E'giardino privato',E'piscina']::text[] WHERE id = 13;
UPDATE public.immobili SET codice = E'Vallarsa/FondazionePrada', titolo = E'BILOCALE RISTRUTTURATO IN VENDITA IN FONDAZIONE PRADA', categoria = E'Appartamento', citta = E'Milano', zona = E'Fondazione Prada', indirizzo = E'Via Vallarsa 22', piano = E'', stato = E'Ristrutturato', classe_energetica = E'G', riscaldamento = E'Autonomo', descrizione = E'A pochi passi dalla Fondazione Prada e nelle immediate vicinanze di Porta Romana, proponiamo in vendita uno splendido bilocale di 52 mq, ristrutturato e disponibile da subito.\nL\u2019immobile, situato al primo piano alto di un contesto tranquillo e ben abitato, si compone di ingresso, luminoso soggiorno con angolo cottura, valorizzato da doppie finestre e da una splendida doppia esposizione a Sud ed Est, ampia camera matrimoniale con ripostiglio in quota e bagno completamente nuovo, mai utilizzato.\nCompleta la propriet\u00e0 una cantina di 7 mq, particolarmente spaziosa. Riscaldamento autonomo e spese condominiali contenute, pari a circa 700 \u20ac annui.\n\nLa posizione \u00e8 uno dei punti di forza: la zona della Fondazione Prada, grazie alla vicinanza dello Scalo Romana, del futuro Villaggio Olimpico, dell\u2019Universit\u00e0 Bocconi e della metropolitana, \u00e8 oggi una delle aree pi\u00f9 richieste e in maggiore rivalutazione di Milano.\n\nSoluzione ideale sia come prima casa sia come investimento, grazie all\u2019elevata richiesta di locazioni.\n\nLe immagini arredate presenti nell\u2019annuncio sono render fotorealistici realizzati a scopo illustrativo per mostrare una possibile soluzione di arredo. L\u2019immobile viene venduto completamente vuoto.\n\nPer maggiori informazioni o per fissare una visita, non esitate a contattarci.\nStudio Arte Immobiliare.', caratteristiche = '{}'::text[] WHERE id = 15;
UPDATE public.immobili SET codice = E'PLINIO', titolo = E'MILANO \u2013 VIA PLINIO 14', categoria = E'Appartamento', citta = E'Milano', zona = E'Porta Venzia', indirizzo = E'Via Plinio 14', piano = E'3', stato = E'Buono', classe_energetica = E'F', riscaldamento = E'Centralizzato', descrizione = E'A pochi passi dalla fermata MM1 Lima e da Corso Buenos Aires, in una delle zone pi\u00f9 richieste e servite di Milano, proponiamo in locazione un ampio appartamento situato al terzo piano di un elegante stabile signorile con ascensore.\n\nL\u2019immobile gode di una piacevole vista aperta sul verde dei giardini circostanti, una caratteristica rara e particolarmente apprezzata in una posizione cos\u00ec centrale.\n\nL\u2019appartamento si sviluppa con una distribuzione degli spazi funzionale e luminosa. L\u2019ingresso si apre su un comodo disimpegno che conduce ai diversi ambienti della casa. La cucina \u00e8 abitabile e dotata di balcone. L\u2019originario soggiorno \u00e8 stato trasformato in una spaziosa camera matrimoniale con un pratico angolo living. Completano la propriet\u00e0 altre due camere matrimoniali di generose dimensioni, una delle quali dispone di un secondo balcone, oltre a un bagno finestrato e ad ulteriori spazi di disimpegno.\n\nL\u2019immobile \u00e8 dotato di aria condizionata ed \u00e8 una soluzione ideale per studenti e giovani professionisti. La posizione \u00e8 particolarmente strategica per raggiungere in pochi minuti il Politecnico di Milano, l\u2019Istituto Marangoni, l\u2019Universit\u00e0 degli Studi di Milano e altri importanti istituti universitari della citt\u00e0, grazie agli ottimi collegamenti con la metropolitana e i mezzi pubblici. La zona offre inoltre supermercati, negozi, ristoranti, bar e tutti i principali servizi comodamente raggiungibili a piedi.\nCanone di locazione: \u20ac 2.000/mese.\nSpese condominiali: \u20ac 150/mese, comprensive di riscaldamento centralizzato, ascensore e servizi condominiali.\nDisponibile da subito.\nPer maggiori informazioni o per fissare una visita, contattate Studio Arte Immobiliare.', caratteristiche = '{}'::text[] WHERE id = 16;
UPDATE public.immobili SET codice = E'Sidoli', titolo = E'Trilocale ampio in palazzo d''epoca \u2013 Citt\u00e0 Studi, Via Sidoli 19, Milano', categoria = E'Appartamento', citta = E'Milano', zona = E'Citt\u00e0 Studi - Susa', indirizzo = E'Via Sidoli 19', piano = E'1', stato = E'Buono', classe_energetica = E'G', riscaldamento = E'Centralizzato', descrizione = E'Trilocale ampio in palazzo d''epoca \u2013 Citt\u00e0 Studi, Via Sidoli 19, Milano\n\nNel cuore di Citt\u00e0 Studi, in un elegante e prestigioso palazzo storico, proponiamo in affitto un luminoso appartamento di 83 mq commerciali, situato al primo piano di uno stabile senza ascensore. L''immobile si sviluppa con ingresso su disimpegno, due camere matrimoniali, soggiorno con angolo cottura e bagno, offrendo una soluzione comoda e ben proporzionata, ideale per studenti, funzionale e ben collegato.\n\nLa posizione \u00e8 tra le pi\u00f9 richieste e servite di Milano, a pochi passi dalle principali universit\u00e0, prima fra tutte il Politecnico di Milano, e comodissima ai mezzi: la fermata della metropolitana Susa si raggiunge in appena cinque minuti a piedi. Ottimo anche il collegamento con il Passante Ferroviario, con la stazione di Dateo praticamente dietro l''angolo.\nL''appartamento \u00e8 disponibile dal 1\u00b0 settembre.\n\nIl canone di locazione richiesto \u00e8 di 1.460 euro al mese, a cui si aggiungono 180 euro di spese condominiali che comprendono il riscaldamento, il servizio di portineria (attivo a mezza giornata) e tutte le spese relative alla gestione del palazzo, salvo conguaglio. Il pagamento \u00e8 previsto con cadenza trimestrale ed \u00e8 richiesta una cauzione pari a tre mensilit\u00e0. Si segnala che all''interno dello stabile non \u00e8 disponibile un posto per le biciclette e moto.\n\nPer maggiori informazioni e per fissare una visita, non esitate a contattarci.\nStudio Arte Immobiliare.', caratteristiche = '{}'::text[] WHERE id = 17;
UPDATE public.immobili SET codice = E'Liberty 13', titolo = E'PORTA VENEZIA | TRILOCALE ULTIMO PIANO \u2013 LUMINOSISSIMO', categoria = E'Appartamento', citta = E'Milano', zona = E'Porta Venezia', indirizzo = E'Via Antonio Stoppani 40', piano = E'5', stato = E'Ristrutturato', classe_energetica = E'E', riscaldamento = E'Autonomo', descrizione = E'Proponiamo in affitto un ampio trilocale situato all\u2019ultimo piano di un elegante palazzo in stile Liberty, caratterizzato da spazi generosi e da una luminosit\u00e0 eccezionale. La distribuzione interna prevede ingresso su ampio disimpegno, soggiorno con cucina a vista, due ampie camere matrimoniali e due bagni finestrati con box doccia.\nL\u2019appartamento \u00e8 disponibile da subito, con un canone mensile di \u20ac 2.000 + \u20ac 150 di spese e deposito cauzionale pari a tre mensilit\u00e0. Si precisa che non \u00e8 presente l\u2019aria condizionata.\nLa posizione \u00e8 strategica e particolarmente apprezzata da studenti e giovani professionisti. L\u2019appartamento \u00e8 ottimamente collegato ai mezzi pubblici e permette di raggiungere facilmente il Politecnico di Milano, Istituto Marangoni, Universit\u00e0 degli Studi di Milano, la Bocconi e le principali universit\u00e0 della citt\u00e0. Inoltre, la fermata della metropolitana M4 Dateo, raggiungibile in circa 10 minuti a piedi, consente collegamenti rapidi con il centro di Milano, l\u2019Aeroporto di Linate e le principali zone della citt\u00e0.\nLa zona offre inoltre supermercati, negozi, ristoranti, bar e tutti i principali servizi raggiungibili comodamente a piedi.\nPer maggiori informazioni o per fissare una visita non esitate a contattarci.', caratteristiche = '{}'::text[] WHERE id = 18;
UPDATE public.immobili SET codice = E'Anna', titolo = E'BILOCALE IN PORTA VENEZIA', categoria = E'Appartamento', citta = E'Milano', zona = E'Porta Venezia', indirizzo = E'Via Antonio Stoppani 40', piano = E'1', stato = E'Ristrutturato', classe_energetica = E'E', riscaldamento = E'Autonomo', descrizione = E'Proponiamo a Milano all''interno di un palazzo in stile Liberty di inizio 900, bilocale COMPLETAMENTE RISTRUTTURATO situato al primo piano con ascensore, servizio di portineria tutto il giorno e completamente arredato.\nL\u2019appartamento \u00e8 cosi composto: ingresso su soggiorno con cucina completa, camera matrimoniale ed infine bagno con box doccia. Il canone mensile richiesto \u00e8 di \u20ac 1.400 pi\u00f9 \u20ac100 di spese condominiali che coprono il servizio portineria tutto il giorno, illuminazione dello stabile, pulizia condominiale, ascensore, Wi-fi. Presente pinguino per raffredamento ambiente come "aria condizionata", utenze a parte, riscaldamento autonomo.\nL''immobile si trova in una zona ben servita dai mezzi pubblici, in particolare dalla metropolitana Porta Venezia situata a 13 minuti a piedi, dal passante ferroviario e da vari mezzi di superficie. L''area \u00e8 caratterizzata dalla sua vicinanza al centro e per la presenza di molteplici negozi di ogni genere, da quelli di prima necessit\u00e0 ai negozi di antiquariato, ai ristoranti ricercati e raffinati a quelli etnici e pi\u00f9\u2019 a portata di mano.\nRICHIESTE OTTIME REFERENZE.\nCONSIGLIABILE LA VISIONE!\nDisponibile da subito.\nPer maggiori informazioni e visite non esitate a contattarci.', caratteristiche = '{}'::text[] WHERE id = 19;
UPDATE public.recensioni SET testo = E'Molto professionali ed efficaci in ogni momento della vendita, dalla preparazione delle bellissime foto all''assistenza al compromesso e al rogito. Sempre disponibili per soddisfare ogni nostra richiesta. Grazie!' WHERE nome = E'Davide';
UPDATE public.recensioni SET testo = E'Mi sono trovato davvero bene. Tutti sono stati gentili, disponibili e mi hanno seguito con attenzione dall''inizio alla fine. Consiglio questa agenzia, ottimo servizio!' WHERE nome = E'MxR Rodax';
UPDATE public.recensioni SET testo = E'Studio immobiliare veramente competente. Eccellente nell''esporre trattative con professionalit\u00e0 e cortesia. Bravo Giulio, sei molto professionale e gentile.' WHERE nome = E'Luca Volpi';
UPDATE public.impostazioni SET valore = E'Sensibilit\u00e0, tecnica ed esperienza al servizio del tuo immobile, tra Milano, Como e la Brianza.' WHERE chiave = 'hero_sottotitolo';
SELECT id, titolo FROM public.immobili WHERE id IN (17, 15) ORDER BY id;
